// Normalizar clientes recebidos
const clientes = $input.first().json.body.clientes || [];
return clientes.map(c => ({ json: c }));

// Cruzamento dos dados do cliente com os produtos do CSV
const cliente = $input.item.json;
const opcoes = $('Processar CSV').all().map(item => item.json);

const produtosPerfil = opcoes.filter(op => op.perfil && op.perfil.toLowerCase() === cliente.perfil.toLowerCase());

const promptIA = `Voce e um especialista em investimentos e consultoria financeira de alto nivel da assessoria Alpha Invest.
Elabore uma mensagem personalizada, profissional, acolhedora e encorajadora para o seguinte cliente:

- Nome: ${cliente.nome}
- Email: ${cliente.email}
- Saldo em conta para aporte: ${cliente.saldo}
- Perfil de investidor: ${cliente.perfil}

Opcoes de produtos disponiveis compativeis com o perfil:
${JSON.stringify(produtosPerfil, null, 2)}

Diretrizes da mensagem:
1. Cumprimente o cliente cordialmente pelo nome.
2. Destaque os pontos fortes do perfil dele (${cliente.perfil}) e relacione de forma consultiva ao seu saldo disponivel (${cliente.saldo}).
3. Explique sucintamente por que os produtos listados fazem sentido para a estrategia dele.
4. Finalize com um Call-to-Action (CTA) convidando-o para tirar duvidas ou confirmar os aportes.
5. Nao invente produtos fora da lista. Seja claro, conciso e elegante.`;

return [{
  json: {
    ...cliente,
    produtos_compativeis: produtosPerfil,
    prompt_ia: promptIA
  }
}];

// Consolidar saida formatada
const item = $input.first().json;
return [{
  json: {
    cliente: $('Cruzar Dados e Montar Prompt').item.json.nome,
    email: $('Cruzar Dados e Montar Prompt').item.json.email,
    perfil: $('Cruzar Dados e Montar Prompt').item.json.perfil,
    saldo: $('Cruzar Dados e Montar Prompt').item.json.saldo,
    produtos_recomendados: $('Cruzar Dados e Montar Prompt').item.json.produtos_compativeis,
    mensagem_ia: item.output || item.text,
    gerado_em: new Date().toISOString()
  }
}];
